import "./loader.css";
import loaderImg from "../../assets/loader.png";

const Loader = () => {
  return (
    <div className="loader-wrapper">
      <img src={loaderImg} alt="Loading..." className="loader-img"  style={{ width: "160px", height: "160px" }}/>
      <p>Loading...</p>
    </div>
  );
};

export default Loader;
