import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { API_ENDPOINTS } from "../../../app/apiroutes";

import {
    TextField,
    Button,
    InputAdornment,
    IconButton,
    Checkbox,
    Alert,
    CircularProgress
} from '@mui/material';

import {
    Visibility,
    VisibilityOff,
    Email,
    Lock
} from '@mui/icons-material';

import { FaShoppingCart } from 'react-icons/fa';
import './Auth.css';

const Login = () => {

    const navigate = useNavigate();

    const [credentials, setCredentials] = useState({
        email: '',
        password: '',
        rememberMe: false
    });

    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [loginAttempts, setLoginAttempts] = useState(0);

    useEffect(() => {
    const token = localStorage.getItem("adminToken");

    if (token && window.location.pathname === "/admin/login") {
        navigate("/admin/dashboard", { replace: true });
    }

    const savedEmail = localStorage.getItem('rememberedEmail');
    if (savedEmail) {
        setCredentials(prev => ({
            ...prev,
            email: savedEmail,
            rememberMe: true
        }));
    }
}, []);

    const handleChange = (e) => {
        const { name, value, checked, type } = e.target;

        setCredentials(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));

        setError('');
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (loginAttempts >= 3) {
            setError('Too many failed attempts');
            return;
        }

        setLoading(true);
        setError('');

        try {
            const response = await fetch(API_ENDPOINTS.ADMIN_LOGIN, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(credentials),
            });

            const data = await response.json();

            if (!response.ok || !data.success) {
                throw new Error(data.message || 'Login failed');
            }

            localStorage.setItem('adminToken', data.token);
            localStorage.setItem('adminUser', JSON.stringify(data.admin));

            if (credentials.rememberMe) {
                localStorage.setItem('rememberedEmail', credentials.email);
            } else {
                localStorage.removeItem('rememberedEmail');
            }
            window.location.reload();

        } catch (err) {
            setLoginAttempts(prev => prev + 1);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="auth-container d-flex justify-content-center align-items-center">

            <div className="auth-card p-4">

                {/* Header */}
                <div className="text-center mb-4">
                    <div className="d-flex justify-content-center align-items-center gap-2">
                        <FaShoppingCart size={30} color="#0d6efd" />
                        <div>
                            <h3 className="mb-0 fw-bold">My Trip Plan</h3>
                            <small className="text-muted">Admin Dashboard</small>
                        </div>
                    </div>

                    <p className="text-muted mt-2">
                        Sign in to access the admin panel
                    </p>
                </div>

                {/* Error */}
                {error && (
                    <Alert severity="error" className="mb-3">
                        {error}
                    </Alert>
                )}

                {/* Form */}
                <form onSubmit={handleSubmit}>

                    {/* Email */}
                    <TextField
                        fullWidth
                        label="Email Address"
                        name="email"
                        value={credentials.email}
                        onChange={handleChange}
                        margin="normal"
                        InputProps={{
                            startAdornment: (
                                <InputAdornment position="start">
                                    <Email />
                                </InputAdornment>
                            )
                        }}
                    />

                    {/* Password */}
                    <TextField
                        fullWidth
                        label="Password"
                        type={showPassword ? "text" : "password"}
                        name="password"
                        value={credentials.password}
                        onChange={handleChange}
                        margin="normal"
                        InputProps={{
                            startAdornment: (
                                <InputAdornment position="start">
                                    <Lock />
                                </InputAdornment>
                            ),
                            endAdornment: (
                                <InputAdornment position="end">
                                    <IconButton onClick={() => setShowPassword(!showPassword)}>
                                        {showPassword ? <VisibilityOff /> : <Visibility />}
                                    </IconButton>
                                </InputAdornment>
                            )
                        }}
                    />

                    {/* Options */}
                    <div className="d-flex justify-content-between align-items-center mt-2">

                        <div className="d-flex align-items-center">
                            <Checkbox
                                checked={credentials.rememberMe}
                                onChange={handleChange}
                                name="rememberMe"
                                size="small"
                            />
                            <small>Remember me</small>
                        </div>

                    </div>

                    {/* Button */}
                    <Button
                        type="submit"
                        fullWidth
                        variant="contained"
                        className="mt-3"
                        style={{
                            padding: '12px',
                            borderRadius: '10px',
                            background: 'linear-gradient(90deg, #0dcaf0, #198754)'
                        }}
                        disabled={loading}
                    >
                        {loading ? <CircularProgress size={22} /> : 'Sign In'}
                    </Button>

                    {/* Attempts */}
                    {loginAttempts > 0 && (
                        <small className="text-danger d-block mt-2 text-center">
                            Attempts: {loginAttempts}/3
                        </small>
                    )}

                </form>

                {/* Footer */}
                <div className="text-center mt-4">
                    <small className="text-success">
                        🔒 Secure login with encrypted connection
                    </small>
                </div>

            </div>

            {/* Background same rahega CSS se */}
            <div className="auth-background">
                <div className="shape shape-1"></div>
                <div className="shape shape-2"></div>
                <div className="shape shape-3"></div>
            </div>

        </div>
    );
};

export default Login;