import React, { useState, useEffect } from 'react';
import { FaBox, FaShoppingCart, FaUsers, FaChartLine } from 'react-icons/fa';
import StatsCard from '../../components/StatsCard/StatsCard';
import './Dashboard.css';
import useDocumentTitle from '../../../../hooks/useDocumentTitle';
import { API_ENDPOINTS } from "../../../../app/apiroutes";
import { IconButton } from '@mui/material';
import { Visibility } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';

const Dashboard = () => {
  useDocumentTitle('Dashboard');
  const navigate = useNavigate();
  const [stats, setStats] = useState({
    totalProducts: 0,
    totalOrders: 0,
    totalCustomers: 0,
    totalRevenue: 0,
    orderStatus: {},
    recentOrders: []
  });

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchDashboardStats = async () => {
      try {
        const token = localStorage.getItem('adminToken');

        if (!token) {
          throw new Error('Unauthorized. Please login again.');
        }

        const response = await fetch(API_ENDPOINTS.ADMIN_DASHBOATD,
          {
            method: 'GET',
            headers: {
              'Content-Type': 'application/json',
              Authorization: `Bearer ${token}`,
            },
          }
        );

        const result = await response.json();

        if (!response.ok || !result.success) {
          localStorage.removeItem('adminToken');
          localStorage.removeItem('adminUser');
          window.location.href = '/admin/login';
          // throw new Error(result.message || 'Failed to load dashboard data');
        }

        const { totals, revenueStats, orderStatus, recentOrders } = result.data;

        setStats({
          totalProducts: totals.products || 0,
          totalOrders: totals.orders || 0,
          totalCustomers: totals.customers || 0,
          totalRevenue: Number(totals?.revenue || 0),
          orderStatus: orderStatus || {},
          recentOrders: recentOrders ? recentOrders : []
        });

      } catch (err) {
        console.error(err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchDashboardStats();
  }, []);

  const handleViewOrder = (orderId) => {
    navigate(`/admin/tour-orders/view/${orderId}`);
  };

  const statCards = [
    {
      title: 'Total Products',
      value: stats.totalProducts,
      icon: <FaBox />,
      color: '#3498db'
    },
    {
      title: 'Total Orders',
      value: stats.totalOrders,
      icon: <FaShoppingCart />,
      color: '#2ecc71'
    },
    {
      title: 'Total Customers',
      value: stats.totalCustomers,
      icon: <FaUsers />,
      color: '#e74c3c'
    },
    {
      title: 'Total Revenue',
      value: `₹${stats.totalRevenue.toFixed(2)}`,
      icon: <FaChartLine />,
      color: '#f39c12'
    }
  ];

  if (loading) {
    return <div className="dashboard">Loading dashboard...</div>;
  }

  if (error) {
    return <div className="dashboard error">{error}</div>;
  }

  return (
    <div className="dashboard">
      <h1>Dashboard Overview</h1>

      <div className="stats-grid">
        {statCards.map((card, index) => (
          <StatsCard key={index} {...card} />
        ))}
      </div>
      <div className="order-status-section">
        <div className="stats-grid">
          {Object.entries(stats.orderStatus).map(([status, count]) => (
            <div className="stats-card" style={{ borderTop: `4px solid white` }}>
              <div className="stats-content">
                <h3>{status}</h3>
                <p className="stats-value">{count}</p>
              </div>
              <div className="stats-icon">
                <FaChartLine />
              </div>
            </div>
          ))}
        </div>
      </div>
      {/* Recent Orders Table */}
      <div className="recent-orders">
        <h2>Recent Orders</h2>

        {!stats?.recentOrders || stats.recentOrders.length === 0 ? (
          <p>No recent orders found.</p>
        ) : (
          <table className="orders-table">
            <thead>
              <tr>
                <th>Order No</th>
                <th>Customer</th>
                <th>Total Amount</th>
                <th>Status</th>
                <th>Date</th>
                <th>Action</th>
              </tr>
            </thead>

            <tbody>
              {stats?.recentOrders?.map((order) => (
                <tr key={order.id}>
                  <td>{order.order_number || order.id}</td>

                  <td>
                    {order.customer_name || order.phone_number || "Guest"}
                  </td>

                  <td>
                    ₹{order.pay_price ? Number(order.pay_price).toFixed(2) : "0.00"}
                  </td>

                  <td>
                    <span className={`status-badge ${order.payment_status}`}>
                      {order.payment_status}
                    </span>
                  </td>

                  <td>
                    {order.created_at
                      ? new Date(order.created_at).toLocaleDateString()
                      : "-"}
                  </td>
                  <td>
                    <IconButton
                      size="small"
                      color="primary"
                      onClick={() => handleViewOrder(order.id)}
                      title="View Details"
                    >
                      <Visibility fontSize="small" />
                    </IconButton>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

    </div>
  );
};

export default Dashboard;
