import React, { useState } from 'react';
import {
  AppBar,
  Toolbar,
  IconButton,
  Typography,
  Badge,
  Menu,
  MenuItem,
  Avatar
} from '@mui/material';
import {
  Menu as MenuIcon,
  Notifications,
  Logout
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../../auth/admin/AuthContext';
import { useEffect } from 'react';
import API_BASE_URL from "../../../../app/apiroutes";

const TopBar = ({ onToggleSidebar }) => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [anchorEl, setAnchorEl] = useState(null);
  const [stats, setStats] = useState(null);


  useEffect(() => {
    const fetchStats = async () => {
      try {
        const response = await fetch(`${API_BASE_URL}/api/orders/stats?order_type=0`, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('adminToken')}`
          }
        });

        const data = await response.json();

        console.log("API DATA:", data);

        if (data.success) {
          setStats({ ...data.data }); // ✅ force update
        }
      } catch (error) {
        console.error("Error fetching stats:", error);
      }
    };

    fetchStats();

    const interval = setInterval(fetchStats, 3000);
    // return () => clearInterval(interval);

  }, []);

  return (
    <AppBar position="fixed" sx={{
      backgroundColor: '#072360'
    }}>
      <Toolbar>
        {/* MOBILE MENU BUTTON */}
        <IconButton
          color="inherit"
          edge="start"
          onClick={onToggleSidebar}
          sx={{ mr: 2, display: { sm: 'none' } }}
        >
          <MenuIcon />
        </IconButton>

        <Typography variant="h6" sx={{ flexGrow: 1 }}>
          E-Tour Admin
        </Typography>

        <IconButton color="inherit">
          <Badge badgeContent={stats?.totalOrders || 0} color="error">
            <Notifications />
          </Badge>
        </IconButton>

        <IconButton onClick={(e) => setAnchorEl(e.currentTarget)}>
          <Avatar src={user?.avatar}>
            {user?.name?.[0]}
          </Avatar>
        </IconButton>

        <Menu anchorEl={anchorEl} open={Boolean(anchorEl)} onClose={() => setAnchorEl(null)}>
          <MenuItem onClick={logout}>
            <Logout fontSize="small" sx={{ mr: 1 }} /> Logout
          </MenuItem>
        </Menu>
      </Toolbar>
    </AppBar>
  );
};

export default TopBar;
