import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Chip,
  Fade,
  Backdrop,
  IconButton
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import LocationOnIcon from "@mui/icons-material/LocationOn";
import API_BASE_URL from "../../../../app/apiroutes";
import useDocumentTitle from "../../../../hooks/useDocumentTitle";
import SEO from "../../../../hooks/SEO";

const Gallery = () => {
  useDocumentTitle('Gallery');
  const [images, setImages] = useState([]);
  const [selectedImage, setSelectedImage] = useState(null);
  const [hoveredId, setHoveredId] = useState(null);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/gallery/list`)
      .then(res => res.json())
      .then(data => setImages(data || []));
  }, []);

  return (
    <>
    <SEO
        title="Gallery | Ujjain Tours, Mahakal Darshan,omkareshwar Darshan,baglamukhi temple & Travel Moments"
        description="Explore our gallery showcasing Mahakal Darshan, Ujjain tours, Omkareshwar trips, and memorable travel experiences with Swastik Tours & Travels." 
        />
    <Box sx={{ background: "#f5f7fa", minHeight: "100vh", py: 5 }}>
      
      {/* GRID */}
      <Box
        sx={{
          maxWidth: "1200px",
          mx: "auto",
          display: "grid",
          gridTemplateColumns: {
            xs: "1fr",
            sm: "1fr 1fr",
            md: "repeat(3, 1fr)"
          },
          gap: 4,
          px: 2
        }}
      >
        {images.map((img) => (
          <Box
            key={img.id}
            onMouseEnter={() => setHoveredId(img.id)}
            onMouseLeave={() => setHoveredId(null)}
            onClick={() => setSelectedImage(img)}
            sx={{
              position: "relative",
              borderRadius: "20px",
              overflow: "hidden",
              cursor: "pointer",
              transition: "0.4s",
              '&:hover': {
                transform: "scale(1.05)",
                boxShadow: "0 20px 40px rgba(0,0,0,0.2)"
              }
            }}
          >
            {/* IMAGE */}
            <img
              src={img.image}
              alt="gallery"
              style={{
                width: "100%",
                height: "280px",
                objectFit: "cover",
                transition: "0.5s",
                transform: hoveredId === img.id ? "scale(1.1)" : "scale(1)"
              }}
            />

            {/* GRADIENT */}
            <Box
              sx={{
                position: "absolute",
                bottom: 0,
                left: 0,
                width: "100%",
                height: "60%",
                background:
                  "linear-gradient(to top, rgba(0,0,0,0.8), transparent)"
              }}
            />

            {/* TEXT */}
            <Typography
              sx={{
                position: "absolute",
                bottom: 15,
                left: 15,
                color: "#fff",
                fontWeight: "bold"
              }}
            >
              Image #{img.id}
            </Typography>

            {/* CHIP */}
            <Chip
              icon={<LocationOnIcon />}
              label="View"
              size="small"
              sx={{
                position: "absolute",
                top: 15,
                right: 15,
                background: "rgba(255,255,255,0.8)"
              }}
            />
          </Box>
        ))}
      </Box>

      {/* MODAL */}
      <Backdrop
        open={!!selectedImage}
        onClick={() => setSelectedImage(null)}
        sx={{ zIndex: 1300 }}
      >
        <Fade in={!!selectedImage}>
          <Box
            sx={{
              width: "90%",
              maxWidth: "800px",
              borderRadius: "20px",
              overflow: "hidden",
              position: "relative"
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <IconButton
              onClick={() => setSelectedImage(null)}
              sx={{
                position: "absolute",
                top: 10,
                right: 10,
                background: "#fff"
              }}
            >
              <CloseIcon />
            </IconButton>

            {selectedImage && (
              <img
                src={selectedImage.image}
                alt=""
                style={{ width: "100%", height: "500px", objectFit: "cover" }}
              />
            )}
          </Box>
        </Fade>
      </Backdrop>
    </Box>
    </>
  );
};

export default Gallery;