import React, { useEffect, useState } from "react";
import axios from "axios";
import { Container, Row, Col, Card, Button } from "react-bootstrap";
import { IconButton } from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";

import API_BASE_URL from "../../../../app/apiroutes";

const GalleryUpload = () => {
  const [images, setImages] = useState([]);
  const [file, setFile] = useState(null);

  // 👉 Load Images
  const fetchImages = async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/api/gallery/list`, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("adminToken")}`
        }
      });
      setImages(res.data); // expect [{id, image}]
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    fetchImages();
  }, []);

  // 👉 Upload
  const handleUpload = async () => {
    if (!file) return;

    const formData = new FormData();
    formData.append("image", file);

    try {
      await axios.post(`${API_BASE_URL}/api/gallery/add`, formData, {
        headers: {
          "Content-Type": "multipart/form-data",
          Authorization: `Bearer ${localStorage.getItem("adminToken")}`
        },
      });

      setFile(null);
      fetchImages();
    } catch (err) {
      console.log(err);
    }
  };

  // 👉 Delete (by ID)
  const handleDelete = async (id) => {
    try {
      await axios.get(`${API_BASE_URL}/api/gallery/delete/${id}`, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("adminToken")}`
        }
      });
      fetchImages();
    } catch (err) {
      console.log(err);
    }
  };

  return (
    <Container className="py-4">
      <h3 className="text-center mb-4">Image Gallery</h3>

      {/* Upload */}
      <div className="d-flex gap-2 mb-4">
        <input
          type="file"
          className="form-control"
          onChange={(e) => setFile(e.target.files[0])}
        />
        <Button onClick={handleUpload}>Upload</Button>
      </div>

      {/* Gallery */}
      <Row>
        {images.map((img) => (
          <Col md={3} sm={6} xs={12} key={img.id} className="mb-4">
            <Card className="position-relative">
              <Card.Img
                variant="top"
                src={`${img.image}`}
                style={{ height: "200px", objectFit: "cover" }}
              />

              {/* Delete Button */}
              <IconButton
                onClick={() => handleDelete(img.id)}
                style={{
                  position: "absolute",
                  top: 5,
                  right: 5,
                  background: "#fff",
                }}
              >
                <DeleteIcon color="error" />
              </IconButton>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
};

export default GalleryUpload;