import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Box,
  Container,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Chip,
  Button,
  TextField,
  InputAdornment,
  Grid,
  Card,
  CardContent,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  LinearProgress,
  Alert,
  Stack,
} from '@mui/material';
import {
  Search,
  Visibility,
  Edit,
  Refresh,
  FilterList,
  CheckCircle,
  Cancel,
  PendingActions,
  TrendingUp,
} from '@mui/icons-material';
import useDocumentTitle from '../../../../hooks/useDocumentTitle';
import API_BASE_URL from "../../../../app/apiroutes";

const PickupOrderList = () => {
  useDocumentTitle('Tour Orders Management');
  const navigate = useNavigate();

  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [stats, setStats] = useState(null);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [totalOrders, setTotalOrders] = useState(0);
  const [paymentFilter, setPaymentFilter] = useState('all');
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [newStatus, setNewStatus] = useState('');

  // Fetch orders
  const fetchOrders = async () => {
    try {
      setLoading(true);
      setError(null);

      const params = new URLSearchParams({
        page: page + 1,
        limit: rowsPerPage,
      });

      if (search) params.append('search', search);
      if (paymentFilter !== 'all') params.append('payment_status', paymentFilter);
      params.append('pageName', "pick");
      const response = await fetch(`${API_BASE_URL}/api/orders?${params}`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('adminToken')}` }
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      if (data.success) {
        setOrders(data.data);
        setTotalOrders(data.pagination.total);
      } else {
        throw new Error(data.message || 'Failed to fetch orders');
      }
    } catch (err) {
      setError(err.message);
      console.error('Error fetching orders:', err);
    } finally {
      setLoading(false);
    }
  };

  // Fetch statistics
  const fetchStats = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/orders/stats?order_type=2`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('adminToken')}` }
      });
      const data = await response.json();

      if (data.success) {
        setStats(data.data);
      }
    } catch (err) {
      console.error('Error fetching stats:', err);
    }
  };

  useEffect(() => {
    fetchOrders();
    fetchStats();
  }, [page, rowsPerPage, paymentFilter]);

  const handleSearch = () => {
    setPage(0);
    fetchOrders();
  };

  const handleClearFilters = () => {
    setSearch('');
    setPaymentFilter('all');
    setPage(0);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleViewOrder = (orderId) => {
    navigate(`/admin/tour-orders/view/${orderId}`);
  };

 
  const getStatusChip = (status) => {
    const statusConfig = {
      pending: { color: 'warning', label: 'Pending', icon: <PendingActions /> },
      paid: { color: 'success', label: 'Paid', icon: <CheckCircle /> },
      failed: { color: 'error', label: 'Failed', icon: <Cancel /> },
    };

    const config = statusConfig[status] || { color: 'default', label: status };

    return (
      <Chip
        icon={config.icon}
        label={config.label}
        color={config.color}
        size="small"
        variant="outlined"
        sx={{ fontWeight: 600 }}
      />
    );
  };

  const getPaymentTypeChip = (type) => {
    const typeConfig = {
      full: { color: 'primary', label: 'Full Payment' },
      partial: { color: 'info', label: 'Partial Payment' },
    };

    const config = typeConfig[type] || { color: 'default', label: type };

    return (
      <Chip
        label={config.label}
        color={config.color}
        size="small"
        variant="filled"
        sx={{ fontWeight: 500 }}
      />
    );
  };

  if (loading && orders.length === 0) {
    return (
      <Box sx={{ width: '100%', p: 4 }}>
        <LinearProgress />
        <Typography sx={{ mt: 2 }}>Loading orders...</Typography>
      </Box>
    );
  }

  return (
    <Container maxWidth="xl" sx={{ py: 4 }}>
      {/* Page Header */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" sx={{ fontWeight: 700, mb: 1 }}>
          Tour Orders Management
        </Typography>
        <Typography variant="body1" color="text.secondary">
          Manage and monitor all tour bookings and payments
        </Typography>
      </Box>

      {/* Statistics Cards */}
      {/* Statistics Cards */}
      {stats && (
        <Grid container spacing={3} sx={{ mb: 4 }}>
          {/* Total Orders */}
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ height: '100%', borderRadius: 3 }}>
              <CardContent>
                <Stack direction="row" alignItems="center" spacing={2}>
                  <Box
                    sx={{
                      p: 1.5,
                      borderRadius: '50%',
                      bgcolor: 'primary.light',
                      color: 'primary.main',
                    }}
                  >
                    <TrendingUp />
                  </Box>
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Total Orders
                    </Typography>
                    <Typography variant="h4" fontWeight={700}>
                      {stats.totalOrders}
                    </Typography>
                  </Box>
                </Stack>
              </CardContent>
            </Card>
          </Grid>

          {/* Paid Orders */}
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ height: '100%', borderRadius: 3 }}>
              <CardContent>
                <Stack direction="row" alignItems="center" spacing={2}>
                  <Box
                    sx={{
                      p: 1.5,
                      borderRadius: '50%',
                      bgcolor: 'success.light',
                      color: 'success.main',
                    }}
                  >
                    <CheckCircle />
                  </Box>
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Paid Orders
                    </Typography>
                    <Typography variant="h4" fontWeight={700}>
                      {stats.paidOrders}
                    </Typography>
                  </Box>
                </Stack>
              </CardContent>
            </Card>
          </Grid>

          {/* Pending Orders */}
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ height: '100%', borderRadius: 3 }}>
              <CardContent>
                <Stack direction="row" alignItems="center" spacing={2}>
                  <Box
                    sx={{
                      p: 1.5,
                      borderRadius: '50%',
                      bgcolor: 'warning.light',
                      color: 'warning.main',
                    }}
                  >
                    <PendingActions />
                  </Box>
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Pending Orders
                    </Typography>
                    <Typography variant="h4" fontWeight={700}>
                      {stats.pendingOrders}
                    </Typography>
                  </Box>
                </Stack>
              </CardContent>
            </Card>
          </Grid>

          {/* Total Revenue */}
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ height: '100%', borderRadius: 3 }}>
              <CardContent>
                <Stack direction="row" alignItems="center" spacing={2}>
                  <Box
                    sx={{
                      p: 1.5,
                      borderRadius: '50%',
                      bgcolor: 'info.light',
                      color: 'info.main',
                    }}
                  >
                    ₹
                  </Box>
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Total Revenue
                    </Typography>
                    <Typography variant="h4" fontWeight={700}>
                      ₹{stats.totalRevenue?.toLocaleString('en-IN') || 0}
                    </Typography>
                  </Box>
                </Stack>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {/* Search and Filter Section */}
      <Paper sx={{ p: 3, mb: 3 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={4}>
            <TextField
              fullWidth
              placeholder="Search by Pickup, Drop, Phone, or Transaction ID"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                ),
              }}
              size="small"
            />
          </Grid>

          <Grid item xs={12} md={3}>
            <FormControl fullWidth size="small">
              <InputLabel>Payment Status</InputLabel>
              <Select
                value={paymentFilter}
                label="Payment Status"
                onChange={(e) => setPaymentFilter(e.target.value)}
              >
                <MenuItem value="all">All Status</MenuItem>
                <MenuItem value="pending">Pending</MenuItem>
                <MenuItem value="paid">Paid</MenuItem>
                <MenuItem value="failed">Failed</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} md={5}>
            <Stack direction="row" spacing={2} justifyContent="flex-end">
              <Button
                variant="outlined"
                startIcon={<FilterList />}
                onClick={handleClearFilters}
              >
                Clear Filters
              </Button>
              <Button
                variant="contained"
                startIcon={<Refresh />}
                onClick={() => {
                  fetchOrders();
                  fetchStats();
                }}
              >
                Refresh
              </Button>
            </Stack>
          </Grid>
        </Grid>
      </Paper>

      {/* Error Alert */}
      {error && (
        <Alert severity="error" sx={{ mb: 3 }}>
          Error: {error}
        </Alert>
      )}

      {/* Orders Table */}
      <TableContainer component={Paper} sx={{ mb: 3 }}>
        <Table>
          <TableHead sx={{ bgcolor: 'primary.main' }}>
            <TableRow>
              <TableCell sx={{ color: 'white', fontWeight: 700 }}>ID</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 700 }}>Tour Name</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 700 }}>Pickup Address</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 700 }}>Travel Date</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 700 }}>Persons</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 700 }}>Amount</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 700 }}>Payment Status</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 700 }}>Payment Type</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 700 }}>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={9} align="center" sx={{ py: 3 }}>
                  <LinearProgress sx={{ width: '100%', mb: 2 }} />
                  <Typography>Loading orders...</Typography>
                </TableCell>
              </TableRow>
            ) : orders.length === 0 ? (
              <TableRow>
                <TableCell colSpan={9} align="center" sx={{ py: 3 }}>
                  <Typography color="text.secondary">
                    No orders found
                  </Typography>
                </TableCell>
              </TableRow>
            ) : (
              orders.map((order) => (
                <TableRow key={order.id} hover>
                  <TableCell>
                    <Typography variant="body2" sx={{ fontWeight: 600 }}>
                      #{order.id}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {order.transaction_id ? `TXN: ${order.transaction_id.substring(0, 12)}...` : 'No TXN ID'}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Typography sx={{ fontWeight: 500 }}>
                      {order.tour?.tour_name || 'Tour Name Not Available'}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      ID: {order.tour_id}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2">
                      {order.pickup_address.substring(0, 30)}...
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2">
                      {order.travel_date}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {order.travel_time}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2" sx={{ fontWeight: 600 }}>
                      {order.qty} Persons
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2" sx={{ fontWeight: 700, color: 'primary.main' }}>
                      ₹{order.final_price}
                    </Typography>
                    {order.payment_type === 'partial' && (
                      <Typography variant="caption" color="text.secondary" display="block">
                        Paid: ₹{order.pay_price}
                      </Typography>
                    )}
                  </TableCell>
                  <TableCell>
                    {getStatusChip(order.payment_status)}
                  </TableCell>
                  <TableCell>
                    {getPaymentTypeChip(order.payment_type)}
                  </TableCell>
                  <TableCell>
                    <Stack direction="row" spacing={1}>
                      <IconButton
                        size="small"
                        color="primary"
                        onClick={() => handleViewOrder(order.id)}
                        title="View Details"
                      >
                        <Visibility fontSize="small" />
                      </IconButton>

                    </Stack>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Pagination */}
      <TablePagination
        component="div"
        count={totalOrders}
        page={page}
        onPageChange={handleChangePage}
        rowsPerPage={rowsPerPage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        rowsPerPageOptions={[5, 10, 25, 50]}
      />
    </Container>
  );
};

export default PickupOrderList;