import React, { useEffect, useState } from "react";
import axios from "axios";
import {
  Container,
  Typography,
  Box,
  Grid,
  Skeleton,
  Fade,
  Chip,
  Divider,
  Avatar,
  useTheme,
  useMediaQuery,
  Card,
  CardMedia
} from "@mui/material";
import {
  Flight,
  LocationOn,
  Groups,
  EmojiTransportation,
  BeachAccess,
  Terrain,
  PhotoCamera,
  Star
} from "@mui/icons-material";
import { useNavigate } from "react-router-dom";
import API_BASE_URL from "../../../../app/apiroutes";
import useDocumentTitle from "../../../../hooks/useDocumentTitle";
import SEO from "../../../../hooks/SEO";

const About = () => {
  useDocumentTitle('About');
  const [aboutData, setAboutData] = useState("");
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));


  // Travel specific stats
  const stats = [
    { label: "Tour Destinations", value: "50+", icon: <LocationOn /> },
    { label: "Happy Travelers", value: "10K+", icon: <Groups /> },
    { label: "Tour Packages", value: "200+", icon: <BeachAccess /> },
    { label: "Tour Experience", value: "15+", icon: <Star /> }
  ];

  // Popular destinations for gallery
  const destinations = [
    { name: "Goa Beaches", image: "https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?w=400" },
    { name: "Manali Hills", image: "https://images.unsplash.com/photo-1626010448982-4d629b9c0de6?w=400" },
    { name: "Kerala Backwaters", image: "https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=400" },
    { name: "Rajasthan Deserts", image: "https://images.unsplash.com/photo-1477587458883-47145ed94245?w=400" }
  ];

  useEffect(() => {
    fetchAbout();
  }, []);

  const fetchAbout = async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/v1/api/information/about-us`
      );
      if (res.data.success) {
        setAboutData(res.data.data.value);
      }
    } catch (error) {
      console.error("Error fetching about us:", error);
    } finally {
      setLoading(false);
    }
  };

  const features = [
    {
      icon: <Flight sx={{ fontSize: 40 }} />,
      title: "Hassle-Free Booking",
      desc: "Easy flight, hotel & tour bookings with best price guarantee and instant confirmation."
    },
    {
      icon: <Terrain sx={{ fontSize: 40 }} />,
      title: "Curated Experiences",
      desc: "Handpicked destinations and activities for unforgettable travel memories."
    },
    {
      icon: <EmojiTransportation sx={{ fontSize: 40 }} />,
      title: "24/7 Support",
      desc: "Round-the-clock assistance during your journey for complete peace of mind."
    }
  ];

  return (
    <>
      <SEO
        title={`Swastik Tours & Travels Ujjain | About Us & Our Services`}
        description="Learn about Swastik Tours & Travels Ujjain. We provide Mahakal Darshan booking, Ujjain tour packages, Omkareshwar trips, and reliable travel services with trusted local expertise." 
        />
      <Box sx={{ bgcolor: "#f8fafc", minHeight: "100vh" }}>
        {/* Hero Section - Travel Theme */}
        <Box
          sx={{
            position: "relative",
            minHeight: { xs: "70vh", md: "80vh" },
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            overflow: "hidden",
            "&::before": {
              content: '""',
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundImage: "url('https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?w=1920')",
              backgroundSize: "cover",
              backgroundPosition: "center",
              filter: "brightness(0.4)"
            }
          }}
        >
          <Container maxWidth="lg" sx={{ position: "relative", zIndex: 1, textAlign: "center" }}>
            <Fade in={!loading} timeout={1000}>
              <Box>
                <Chip
                  icon={<Flight sx={{ color: "#fff !important" }} />}
                  label="EXPLORE THE WORLD WITH US"
                  sx={{
                    bgcolor: "rgba(255,255,255,0.15)",
                    color: "white",
                    mb: 3,
                    fontWeight: 600,
                    letterSpacing: 2,
                    backdropFilter: "blur(10px)",
                    border: "1px solid rgba(255,255,255,0.2)"
                  }}
                />
                <Typography
                  variant="h1"
                  sx={{
                    fontSize: { xs: "2.5rem", md: "4.5rem" },
                    fontWeight: 800,
                    mb: 3,
                    color: "white",
                    textShadow: "2px 2px 4px rgba(0,0,0,0.3)"
                  }}
                >
                  Discover Your Next
                  <Box component="span" sx={{ color: "#38bdf8", display: "block" }}>
                    Adventure
                  </Box>
                </Typography>
                <Typography
                  variant="h5"
                  sx={{
                    maxWidth: "700px",
                    mx: "auto",
                    color: "rgba(255,255,255,0.9)",
                    fontWeight: 300,
                    lineHeight: 1.6,
                    mb: 4
                  }}
                >
                  We craft extraordinary travel experiences that create memories lasting a lifetime.
                  From serene beaches to majestic mountains, your journey begins here.
                </Typography>

                {/* Scroll indicator */}
                <Box
                  sx={{
                    width: 30,
                    height: 50,
                    border: "2px solid rgba(255,255,255,0.5)",
                    borderRadius: 15,
                    mx: "auto",
                    position: "relative",
                    "&::before": {
                      content: '""',
                      position: "absolute",
                      top: 8,
                      left: "50%",
                      transform: "translateX(-50%)",
                      width: 6,
                      height: 6,
                      bgcolor: "white",
                      borderRadius: "50%",
                      animation: "bounce 2s infinite"
                    },
                    "@keyframes bounce": {
                      "0%, 100%": { transform: "translateX(-50%) translateY(0)" },
                      "50%": { transform: "translateX(-50%) translateY(10px)" }
                    }
                  }}
                />
              </Box>
            </Fade>
          </Container>

          {/* Wave Bottom */}
          <Box
            sx={{
              position: "absolute",
              bottom: 0,
              left: 0,
              right: 0,
              height: "100px",
              background: "linear-gradient(to top right, #f8fafc 49%, transparent 51%)"
            }}
          />
        </Box>

        {/* Stats Section */}
        <Container maxWidth="lg" sx={{ mt: -5, position: "relative", zIndex: 2 }}>
          <Grid container spacing={{ xs: 1.5, sm: 2, md: 3 }} justifyContent="center">
            {stats.map((stat, index) => (
              <Grid
                item
                xs={6}
                sm={6}
                md={3}
                key={index}
                sx={{
                  display: "flex",
                  justifyContent: "center"
                }}
              >
                <Fade in={!loading} timeout={1000 + index * 200}>
                  <Box
                    sx={{
                      width: "100%",
                      maxWidth: { xs: "100%", sm: 260 },
                      height: { xs: 160, sm: 180, md: 220 },
                      bgcolor: "white",
                      p: { xs: 2, sm: 2.5, md: 3 },
                      borderRadius: { xs: 2, md: 3 },
                      textAlign: "center",
                      boxShadow: "0 10px 40px rgba(0,0,0,0.08)",
                      border: "1px solid rgba(0,0,0,0.05)",
                      transition: "all 0.3s ease",
                      display: "flex",
                      flexDirection: "column",
                      justifyContent: "center",
                      alignItems: "center",
                      gap: { xs: 0.5, md: 1 },
                      "&:hover": {
                        transform: { xs: "none", sm: "translateY(-8px)" },
                        boxShadow: "0 20px 60px rgba(0,0,0,0.12)"
                      }
                    }}
                  >
                    <Avatar
                      sx={{
                        bgcolor: "#0ea5e9",
                        width: { xs: 36, sm: 44, md: 60 },
                        height: { xs: 36, sm: 44, md: 60 },
                        boxShadow: "0 8px 20px rgba(14,165,233,0.3)",
                        fontSize: { xs: "1rem", sm: "1.2rem", md: "1.5rem" }
                      }}
                    >
                      {stat.icon}
                    </Avatar>

                    <Typography
                      variant="h4"
                      fontWeight="bold"
                      color="#0f172a"
                      sx={{
                        fontSize: { xs: "1.5rem", sm: "1.75rem", md: "2.125rem" },
                        lineHeight: 1.2
                      }}
                    >
                      {stat.value}
                    </Typography>

                    <Typography
                      variant="body2"
                      color="text.secondary"
                      fontWeight={500}
                      sx={{
                        fontSize: { xs: "0.75rem", sm: "0.875rem", md: "1rem" },
                        lineHeight: 1.4,
                        maxWidth: "100%",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap"
                      }}
                    >
                      {stat.label}
                    </Typography>
                  </Box>
                </Fade>
              </Grid>
            ))}
          </Grid>
        </Container>

        {/* About Content Section */}
        <Container maxWidth="lg" sx={{ py: { xs: 8, md: 12 } }}>
          <Grid container spacing={6} alignItems="center">
            <Grid item xs={12} md={6}>
              <Fade in={!loading} timeout={1200}>
                <Box>
                  <Typography
                    variant="overline"
                    sx={{ color: "#0ea5e9", fontWeight: 700, letterSpacing: 2 }}
                  >
                    ABOUT OUR COMPANY
                  </Typography>
                  <Typography
                    variant="h2"
                    sx={{
                      fontSize: { xs: "1rem", md: "2rem" },
                      fontWeight: 800,
                      mb: 3,
                      color: "#0f172a",
                      lineHeight: 1.2
                    }}
                  >
                    Making Your Travel Dreams a
                    <Box component="span" sx={{ color: "#0ea5e9" }}> Reality</Box>
                  </Typography>

                  {loading ? (
                    <Box>
                      <Skeleton variant="text" width="100%" height={20} sx={{ mb: 1 }} />
                      <Skeleton variant="text" width="100%" height={20} sx={{ mb: 1 }} />
                      <Skeleton variant="text" width="80%" height={20} />
                    </Box>
                  ) : (
                    <Typography
                      component="div"
                      sx={{
                        fontSize: "1.1rem",
                        lineHeight: 1.8,
                        color: "#475569",
                        mb: 1,
                        "& p": { mb: 1 }
                      }}
                      dangerouslySetInnerHTML={{ __html: aboutData }}
                    />
                  )}
                </Box>
              </Fade>
            </Grid>
          </Grid>
        </Container>

        {/* Features Grid */}
        <Box sx={{ bgcolor: "white", py: { xs: 8, md: 12 } }}>
          <Container maxWidth="lg">
            <Box textAlign="center" mb={8}>
              <Typography
                variant="overline"
                sx={{ color: "#0ea5e9", fontWeight: 700, letterSpacing: 2 }}
              >
                WHY TRAVEL WITH US
              </Typography>
              <Typography
                variant="h2"
                sx={{
                  fontSize: { xs: "2rem", md: "2.5rem" },
                  fontWeight: 800,
                  color: "#0f172a"
                }}
              >
                We Offer The Best Experience
              </Typography>
            </Box>

            <Grid container spacing={4}>
              {features.map((feature, idx) => (
                <Grid item xs={12} md={4} key={idx}>
                  <Box
                    sx={{
                      p: 4,
                      height: "100%",
                      borderRadius: 4,
                      bgcolor: "#f8fafc",
                      transition: "all 0.3s ease",
                      border: "2px solid transparent",
                      "&:hover": {
                        borderColor: "#0ea5e9",
                        transform: "translateY(-5px)",
                        boxShadow: "0 20px 40px rgba(14,165,233,0.1)"
                      }
                    }}
                  >
                    <Box
                      sx={{
                        color: "#0ea5e9",
                        mb: 3,
                        p: 2,
                        bgcolor: "rgba(14,165,233,0.1)",
                        borderRadius: 3,
                        display: "inline-block"
                      }}
                    >
                      {feature.icon}
                    </Box>
                    <Typography variant="h5" fontWeight="bold" gutterBottom color="#0f172a">
                      {feature.title}
                    </Typography>
                    <Typography variant="body1" color="text.secondary" lineHeight={1.7}>
                      {feature.desc}
                    </Typography>
                  </Box>
                </Grid>
              ))}
            </Grid>
          </Container>
        </Box>

        {/* CTA Section */}
        <Box
          sx={{
            position: "relative",
            py: { xs: 8, md: 10 },
            backgroundImage: "url('https://images.unsplash.com/photo-1436491865332-7a61a109cc05?w=1920')",
            backgroundSize: "cover",
            backgroundAttachment: "fixed",
            backgroundPosition: "center",
            "&::before": {
              content: '""',
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              bgcolor: "rgba(15,23,42,0.85)"
            }
          }}
        >
          <Container maxWidth="md" sx={{ position: "relative", zIndex: 1, textAlign: "center" }}>
            <PhotoCamera sx={{ fontSize: 60, color: "#38bdf8", mb: 2 }} />
            <Typography variant="h3" fontWeight="bold" color="white" mb={2}>
              Ready To Start Your Journey?
            </Typography>
            <Typography variant="body1" sx={{ color: "rgba(255,255,255,0.8)", mb: 4, maxWidth: 600, mx: "auto" }}>
              Book your next adventure today and get exclusive deals on flights, hotels, and tour packages.
            </Typography>
            <Box sx={{ display: "flex", gap: { xs: 1.5, sm: 2 }, justifyContent: "center", flexWrap: "nowrap" }}>
              <Box
                component="button"
                sx={{
                  bgcolor: "#0ea5e9",
                  color: "white",
                  border: "none",
                  px: { xs: 3, sm: 6 },
                  py: { xs: 1.5, sm: 2 },
                  borderRadius: 50,
                  fontWeight: "bold",
                  fontSize: { xs: "0.875rem", sm: "1rem" },
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                  whiteSpace: "nowrap",
                  minWidth: { xs: "auto", sm: "auto" },
                  "&:hover": {
                    bgcolor: "#0284c7",
                    transform: "translateY(-2px)",
                    boxShadow: "0 10px 30px rgba(14,165,233,0.3)"
                  }
                }}
                onClick={() => navigate('/trips')}>
                Book Now
              </Box>
              <Box
                component="button"
                sx={{
                  bgcolor: "transparent",
                  color: "white",
                  border: "2px solid white",
                  px: { xs: 3, sm: 6 },
                  py: { xs: 1.5, sm: 2 },
                  borderRadius: 50,
                  fontWeight: "bold",
                  fontSize: { xs: "0.875rem", sm: "1rem" },
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                  whiteSpace: "nowrap",
                  minWidth: { xs: "auto", sm: "auto" },
                  "&:hover": {
                    bgcolor: "white",
                    color: "#0f172a"
                  }
                }}
                onClick={() => navigate('/contact')}>
                Contact Us
              </Box>
            </Box>
          </Container>
        </Box>
      </Box>
    </>
  );
};

export default About;