import { Helmet } from "react-helmet";

const SEO = ({
    title = "Swastik Tours & Travels Ujjain",
    description = "Book Mahakal Darshan in Ujjain with Swastik Tours & Travels. Get VIP darshan, Omkareshwar tours & affordable packages. Call now for booking!",
    keywords = "ujjain tour package, mahakal darshan booking, mahakal tour ujjain, omkareshwar tour package, jyotirlinga yatra, ujjain travel agency, ujjain cab service, mahakal vip darshan booking, madhya pradesh tour packages, spiritual tour india",
    image = "/apple-touch-icon.png",
    url = typeof window !== "undefined" ? window.location.href : "",
    noindex = false,
}) => {
    return (
        <Helmet>
            {/* Basic */}
            <title>{title}</title>
            <meta name="description" content={description} />
            {keywords && <meta name="keywords" content={keywords} />}

            {/* Robots */}
            {noindex ? (
                <meta name="robots" content="noindex, nofollow" />
            ) : (
                <meta name="robots" content="index, follow" />
            )}

            {/* Open Graph */}
            <meta property="og:title" content={title} />
            <meta property="og:description" content={description} />
            <meta property="og:image" content={image} />
            <meta property="og:url" content={url} />

            {/* Twitter */}
            <meta name="twitter:card" content="summary_large_image" />
            <meta name="twitter:title" content={title} />
            <meta name="twitter:description" content={description} />
            <meta name="twitter:image" content={image} />

            {/* Favicon */}
            <link rel="icon" href="/favicon.ico" />
            <link rel="canonical" href={url} />
            <script type="application/ld+json">
                {JSON.stringify({
                    "@context": "https://schema.org",
                    "@type": "TravelAgency",
                    "name": "Swastik Tours & Travels Ujjain",
                    "url": url,
                    "description": description,
                    "address": {
                        "@type": "PostalAddress",
                        "addressLocality": "Ujjain",
                        "addressRegion": "Madhya Pradesh",
                        "addressCountry": "India"
                    },
                    "areaServed": "Ujjain",
                    "serviceType": "Tour and Travel Services"
                })}
            </script>
        </Helmet>
    );
};

export default SEO;