import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FaHome, FaArrowLeft, FaExclamationTriangle } from 'react-icons/fa';
import './NotFound.css';

const NotFound = ({ type = '404' }) => {
  const navigate = useNavigate();

  const messages = {
    '404': {
      title: '404 - Page Not Found',
      message: 'The page you are looking for might have been removed, had its name changed, or is temporarily unavailable.',
      icon: '🔍'
    },
    'unauthorized': {
      title: 'Access Denied',
      message: 'You do not have permission to access this page. Please contact your administrator for access.',
      icon: '🚫'
    }
  };

  const { title, message, icon } = messages[type];

  return (
    <div className="not-found-container">
      <div className="not-found-card">
        <div className="not-found-icon">
          <span role="img" aria-label="error">{icon}</span>
        </div>
        
        <h1>{title}</h1>
        <p className="not-found-message">{message}</p>
        
        <div className="not-found-actions">
          <button onClick={() => navigate(-1)} className="action-btn back">
            <FaArrowLeft /> Go Back
          </button>
          <Link to="/" className="action-btn home">
            <FaHome /> Go Home
          </Link>
        </div>
        
        {type === 'unauthorized' && (
          <div className="unauthorized-info">
            <FaExclamationTriangle />
            <p>If you believe this is an error, please contact the system administrator.</p>
          </div>
        )}
        
        <div className="not-found-footer">
          <p>Need help? <Link to="/contact">Contact Support</Link></p>
        </div>
      </div>
    </div>
  );
};

export default NotFound;