import { useState, useEffect, useRef } from "react";
import { TextField, Snackbar, Alert, Box, CircularProgress } from "@mui/material";
import { LocationOn } from "@mui/icons-material";

const PickupAutocomplete = ({ allowedCities, value, onChange }) => {
  const [toast, setToast] = useState({
    open: false,
    message: "",
    severity: "error",
  });

  const [inputValue, setInputValue] = useState(value || "");
  const [isValidating, setIsValidating] = useState(false);
  const inputRef = useRef(null);
  const autocompleteRef = useRef(null);

  // Initialize Google Places Autocomplete when Google Maps API is available
  useEffect(() => {
    if (window.google && window.google.maps && window.google.maps.places) {
      if (inputRef.current && !autocompleteRef.current) {
        autocompleteRef.current = new window.google.maps.places.Autocomplete(inputRef.current, {
          types: ["address"],
          componentRestrictions: { country: "in" },
        });

        autocompleteRef.current.addListener("place_changed", () => {
          const place = autocompleteRef.current.getPlace();
          if (place.formatted_address) {
            setInputValue(place.formatted_address);
            onChange(place.formatted_address);
          }
        });
      }
    } else {
      // Retry after a short delay if Google Maps not loaded yet
      const timer = setTimeout(() => {
        if (window.google && window.google.maps && window.google.maps.places) {
          if (inputRef.current && !autocompleteRef.current) {
            autocompleteRef.current = new window.google.maps.places.Autocomplete(inputRef.current, {
              types: ["address"],
              componentRestrictions: { country: "in" },
            });

            autocompleteRef.current.addListener("place_changed", () => {
              const place = autocompleteRef.current.getPlace();
              if (place.formatted_address) {
                setInputValue(place.formatted_address);
                onChange(place.formatted_address);
              }
            });
          }
        }
      }, 1000);

      return () => clearTimeout(timer);
    }

    // Cleanup on unmount
    return () => {
      if (autocompleteRef.current) {
        try {
          window.google.maps.event.clearInstanceListeners(autocompleteRef.current);
        } catch (e) {
          // Ignore cleanup errors
        }
        autocompleteRef.current = null;
      }
    };
  }, [onChange]);

  // Update input value when value prop changes
  useEffect(() => {
    if (value !== inputValue) {
      setInputValue(value || "");
    }
  }, [value]);

  const handleChange = (e) => {
    const newValue = e.target.value;
    setInputValue(newValue);
    onChange(newValue);
  };

  const handleBlur = async () => {
    // Skip validation if no input
    if (!inputValue.trim()) return;

    // Skip validation if allowedCities is empty (allow all)
    if (!allowedCities || allowedCities.length === 0) {
      onChange(inputValue);
      return;
    }

    setIsValidating(true);

    // Simple validation - check if input contains any allowed city
    const inputLower = inputValue.toLowerCase();
    const isAllowed = allowedCities.some((city) =>
      inputLower.includes(city.toLowerCase())
    );

    setIsValidating(false);

    if (!isAllowed && allowedCities.length > 0) {
      setToast({
        open: true,
        message: `Pickup allowed only in: ${allowedCities.join(", ")}`,
        severity: "error",
      });
      onChange(inputValue);
    } else {
      onChange(inputValue);
    }
  };

  return (
    <>
      <Box sx={{ position: "relative", mt: 1 }}>
        <TextField
          fullWidth
          inputRef={inputRef}
          label="Pickup Address"
          value={inputValue}
          onChange={handleChange}
          onBlur={handleBlur}
          placeholder="Enter pickup location"
          InputProps={{
            startAdornment: <LocationOn sx={{ color: "action.active", mr: 1 }} />,
            endAdornment: isValidating ? <CircularProgress size={20} /> : null,
          }}
          sx={{ mt: 1, "& .MuiOutlinedInput-root": { borderRadius: 1 } }}
        />
      </Box>

      {/* Show allowed cities hint */}
      {allowedCities && allowedCities.length > 0 && (
        <Box sx={{ mt: 0.5, display: "flex", flexWrap: "wrap", gap: 0.5 }}>
          {allowedCities.slice(0, 3).map((city, index) => (
            <Box
              key={index}
              sx={{
                fontSize: "0.7rem",
                color: "text.secondary",
                bgcolor: "grey.100",
                px: 0.5,
                py: 0.25,
                borderRadius: 0.5,
              }}
            >
              {city}
            </Box>
          ))}
          {allowedCities.length > 3 && (
            <Box sx={{ fontSize: "0.7rem", color: "text.secondary" }}>
              +{allowedCities.length - 3} more
            </Box>
          )}
        </Box>
      )}

      <Snackbar
        open={toast.open}
        autoHideDuration={4000}
        onClose={() => setToast({ ...toast, open: false })}
        anchorOrigin={{ vertical: "top", horizontal: "right" }}
        sx={{ zIndex: (theme) => theme.zIndex.modal + 10, top: { xs: 72, md: 80 } }}
      >
        <Alert severity={toast.severity} variant="filled" onClose={() => setToast({ ...toast, open: false })}>
          {toast.message}
        </Alert>
      </Snackbar>
    </>
  );
};

export default PickupAutocomplete;
