import React from "react";
import { NavLink } from "react-router-dom";
import {
  Box,
  Container,
  Grid,
  Typography,
  IconButton,
  Stack,
  Divider
} from "@mui/material";

import {
  FaFacebookF,
  FaInstagram,
  FaTwitter,
  FaYoutube,
  FaPhoneAlt,
  FaEnvelope,
  FaMapMarkerAlt
} from "react-icons/fa";

const Footer = () => {
  return (
    <Box
      component="footer"
      sx={{
        background: "linear-gradient(135deg, #0b1c2d, #081421)",
        color: "#fff",
        pt: 6
      }}
    >
      <Container maxWidth="lg">
        <Grid container spacing={4}>

          {/* BRAND */}
          <Grid item xs={12} md={3}>
            <Typography variant="h6" fontWeight={700} gutterBottom>
              Ujjain Holiday Planner
            </Typography>
            <Typography variant="body2" color="grey.400">
              <b>Swastik Tour and Travels</b> – A decade of trust in <br/>delivering unforgettable Ujjain tours since 2010.
            </Typography>

            <Stack direction="row" spacing={1} mt={2}>
              {[FaFacebookF, FaInstagram, FaTwitter, FaYoutube].map(
                (Icon, i) => (
                  <IconButton
                    key={i}
                    sx={{
                      color: "#cbd5e1",
                      "&:hover": { color: "#ff9800" }
                    }}
                  >
                    <Icon />
                  </IconButton>
                )
              )}
            </Stack>
          </Grid>

          {/* QUICK LINKS */}
          <Grid item xs={12} md={3}>
            <Typography variant="subtitle1" fontWeight={600} gutterBottom>
              Quick Links
            </Typography>

            <Stack spacing={1}>
              {[
                { label: "Home", path: "/" },
                { label: "Trip", path: "/trips" },
                { label: "Cancellation Policy", path: "/cancellation-policy" },
                { label: "Privacy Policy", path: "/privacy-policy" },
                { label: "Terms & Conditions", path: "/terms-and-conditions" }
              ].map((item) => (
                <Typography
                  key={item.label}
                  component={NavLink}
                  to={item.path}
                  sx={{
                    textDecoration: "none",
                    color: "grey.400",
                    "&:hover": { color: "#ff9800" }
                  }}
                >
                  {item.label}
                </Typography>
              ))}
            </Stack>
          </Grid>

          {/* CONTACT */}
          <Grid item xs={12} md={3}>
            <Typography variant="subtitle1" fontWeight={600} gutterBottom>
              Contact Us
            </Typography>

            <Stack spacing={1}>
              <Typography variant="body2" color="grey.400">
                <FaMapMarkerAlt /> Ujjain, MP (456001)
              </Typography>
              <Typography variant="body2" color="grey.400">
                <FaEnvelope /> bigcat.info@travels.com
              </Typography>
            </Stack>
          </Grid>

          {/* GET IN TOUCH */}
          <Grid item xs={12} md={3}>
            <Typography variant="subtitle1" fontWeight={600} gutterBottom>
              Get In Touch
            </Typography>

            <Stack spacing={1}>
              <Typography variant="body2" color="grey.400">
                <FaPhoneAlt /> +91 0000000000
              </Typography>
              <Typography variant="body2" color="grey.400">
                <FaPhoneAlt /> +91 0000000000
              </Typography>
              <Typography variant="body2" color="grey.400">
                <FaEnvelope /> bigcatbook@gmail.com
              </Typography>
            </Stack>
          </Grid>
        </Grid>

        {/* BOTTOM */}
        <Divider sx={{ my: 4, borderColor: "rgba(255,255,255,0.1)" }} />

        <Typography
          variant="body2"
          align="center"
          color="grey.500"
          pb={2}
        >
          © {new Date().getFullYear()} Ujjain Holiday Planner. All Rights Reserved.
        </Typography>
      </Container>
    </Box>
  );
};

export default Footer;
