import React, { useState, useEffect } from 'react';
import {
  Container,
  Row,
  Col,
  Card,
  Button,
  Form,
  InputGroup,
  Alert
} from 'react-bootstrap';

import {
  Box,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  Typography,
  Rating,
  Skeleton,
  useTheme,
  useMediaQuery
} from '@mui/material';

import LocationOnIcon from '@mui/icons-material/LocationOn';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import FilterListIcon from '@mui/icons-material/FilterList';
import ClearAllIcon from '@mui/icons-material/ClearAll';

import { useNavigate } from 'react-router-dom';
import API_BASE_URL from "../../../../app/apiroutes";
import useDocumentTitle from '../../../../hooks/useDocumentTitle';
import SEO from '../../../../hooks/SEO';

const Trips = () => {
useDocumentTitle('All Tour');
  const [trips, setTrips] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [sortBy, setSortBy] = useState('featured');
  const [searchTerm, setSearchTerm] = useState('');

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const navigate = useNavigate();

  // 🔥 Fetch API
  useEffect(() => {
    const fetchTours = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/v1/api/tour/tours`);
        const result = await res.json();

        const data = result.data.map(tour => ({
          id: tour.id,
          name: tour.tour_name,
          slug: tour.slug,
          image: tour.image,
          location: tour.slug,
          days: tour.days,
          rating: 4.5,
          reviews: Math.floor(Math.random() * 200) + 50
        }));

        setTrips(data);
      } catch (err) {
        setError("Failed to load tours");
      } finally {
        setLoading(false);
      }
    };

    fetchTours();
  }, []);

  // 🔥 Filter + Sort
  const processedTrips = trips
    .filter(trip =>
      trip.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

  // 🔥 Loading UI
  if (loading) {
    return (
      <Container className="py-5">
        <Row>
          {[1, 2, 3].map(i => (
            <Col md={4} key={i}>
              <Skeleton variant="rectangular" height={300} />
            </Col>
          ))}
        </Row>
      </Container>
    );
  }

  // 🔥 Error UI
  if (error) {
    return (
      <Container className="py-5">
        <Alert variant="danger">{error}</Alert>
      </Container>
    );
  }

  return (
    <>
    <SEO
        title="Tour Packages | Mahakal Temple ,Baglamukhi Temple & Omkareshwar Tours"
        description="Browse the best Ujjain tour packages including Mahakal VIP Darshan, Omkareshwar tours,baglamukhi temple, Jyotirlinga yatra, and affordable travel services." 
        />
    <div className="trips-wrapper">

      {/* HEADER */}
      <div className="trips-header">
        <Container>
          <Row className="align-items-center">
            <Col md={6}>
              <Typography variant="h4" className="text-white fw-bold">
                Explore Trips
              </Typography>
            </Col>

            <Col md={6}>
              <InputGroup>
                <Form.Control
                  placeholder="Search trips..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
                <Button variant="light">
                  <FilterListIcon />
                </Button>
              </InputGroup>
            </Col>
          </Row>
        </Container>
      </div>

      {/* GRID */}
      <Container className="py-5">
        <Row className="g-4">

          {processedTrips.map(trip => (
            <Col key={trip.id} xs={12} md={6} lg={4}>

              <Card
                className="trip-card"
                onClick={() => navigate(`/tour-details/${trip.slug}`)}
              >

                {/* IMAGE */}
                <div className="image-wrapper">

                  <Card.Img
                    src={trip.image}
                    className="trip-image"
                  />

                  <div className="overlay"></div>

                  <Chip
                    icon={<AccessTimeIcon fontSize="small" className="me-1" />}
                    label={trip.days}
                    size="small"
                    className="location-chip"
                  />

                </div>

                {/* CONTENT */}
                <Card.Body>
                  <Box className="d-flex align-items-center mb-2 text-muted">
                    <Typography variant="body2" className="trip-title">{trip.name}</Typography>
                  </Box>
                  <Box className="d-flex align-items-center mb-3">
                    <Rating value={trip.rating} size="small" readOnly />
                    <Typography variant="caption" className="ms-1">
                      ({trip.reviews})
                    </Typography>
                  </Box>

                  <Button className="explore-btn w-100">
                    Explore Tour
                  </Button>

                </Card.Body>

              </Card>

            </Col>
          ))}

        </Row>
      </Container>

      {/* 🔥 CSS */}
      <style jsx global>{`

        .trips-header {
          background: linear-gradient(45deg, #38BDF8, #22C55E);
          padding: 40px 0;
        }

        .trip-card {
          border-radius: 20px;
          overflow: hidden;
          border: none;
          transition: 0.4s;
          cursor: pointer;
          backdrop-filter: blur(10px);
        }
.trip-title {
  font-weight: bold;     
  display: -webkit-box;
  -webkit-line-clamp: 2;     
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
}
        .trip-card:hover {
          transform: translateY(-10px);
          box-shadow: 0 20px 50px rgba(34, 197, 94, 0.3);
        }

        .image-wrapper {
          position: relative;
          height: 220px;
          overflow: hidden;
        }

        .trip-image {
          width: 100%;
          height: 100%;
          object-fit: cover;
          transition: 0.6s;
        }

        .trip-card:hover .trip-image {
          transform: scale(1.1);
        }

        .overlay {
          position: absolute;
          bottom: 0;
          width: 100%;
          height: 60%;
          background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
        }

        .location-chip {
          position: absolute;
          top: 10px;
          right: 10px;
          background: rgba(56, 189, 248, 0.2) !important;
          color: #0EA5E9 !important;
        }

        .explore-btn {
          border-radius: 30px !important;
          font-weight: bold !important;
          background: linear-gradient(45deg, #0EA5E9, #16A34A) !important;
          color: #fff !important;
        }
      .trips-wrapper {
        background: linear-gradient(to bottom, #F0F9FF, #ECFDF5);
      }
      `}</style>

    </div>
    </>
  );
};

export default Trips;