import React, { useState } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';

import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  InputAdornment
} from '@mui/material';
import API_BASE_URL from "../../../../app/apiroutes";
import PhoneIcon from '@mui/icons-material/Phone';
import PersonIcon from '@mui/icons-material/Person';
import axios from 'axios';
import useDocumentTitle from '../../../../hooks/useDocumentTitle';
import SEO from '../../../../hooks/SEO';

const Contact = () => {
useDocumentTitle('Contact Us');
  const [formData, setFormData] = useState({
    fullName: '',
    phone: '',
    message: ''
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await axios.post(
        `${API_BASE_URL}/v1/api/information/contact`,
        {
          name: formData.fullName,
          phone: formData.phone,
          message: formData.message
        }
      );
      setFormData({
        fullName: '',
        phone: '',
        message: ''
      });

    } catch (error) {
      console.error(error);

      if (error.response?.data?.message) {
        alert(error.response.data.message);
      } else {
        alert('Something went wrong!');
      }
    }
  };

  return (
    <>
    <SEO
        title="Contact Swastik Tours & Travels Ujjain | Book Tour"
        description="Get in touch with Swastik Tours & Travels Ujjain for Mahakal Darshan booking, tour packages, and travel assistance. Call now for quick support." 
        />
    <div className="container py-5">
      <div className="row g-4 align-items-stretch">

        {/* Left Panel */}
        <div className="col-md-5 d-none d-md-block">
          <Paper
            elevation={6}
            sx={{
              height: '100%',
              borderRadius: 4,
              overflow: 'hidden',
              position: 'relative'
            }}
          >
            <Box
              component="img"
              src="https://images.unsplash.com/photo-1551434678-e076c223a692"
              sx={{
                width: '100%',
                height: '100%',
                objectFit: 'cover',
                position: 'absolute'
              }}
            />

            <Box sx={{ position: 'relative', p: 3 }}>
              <Paper sx={{ p: 3, background: 'rgba(255,255,255,0.9)' }}>
                <Typography variant="h6">Contact Info</Typography>
                <Typography>Phone: 000-234-5678</Typography>
                <Typography>Email: admin@bigcat.com</Typography>
              </Paper>
            </Box>
          </Paper>
        </div>

        {/* Right Panel */}
        <div className="col-12 col-md-7">
          <Paper sx={{ p: 4, borderRadius: 3 }}>
            <Typography variant="h4" sx={{ mb: 2 }}>
              Contact Us
            </Typography>

            <Typography sx={{ mb: 3 }}>
              Fill up the form and then click send
            </Typography>

            <form onSubmit={handleSubmit} className="d-flex flex-column gap-3">

              {/* Full Name */}
              <TextField
                label="Full Name"
                name="fullName"
                value={formData.fullName}
                onChange={handleChange}
                fullWidth
                required
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <PersonIcon />
                    </InputAdornment>
                  )
                }}
              />

              {/* Phone */}
              <TextField
                label="Phone Number"
                name="phone"
                value={formData.phone}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ maxLength: 10 }}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <PhoneIcon />
                    </InputAdornment>
                  )
                }}
              />

              {/* Message */}
              <TextField
                label="Message"
                name="message"
                value={formData.message}
                onChange={handleChange}
                fullWidth
                required
                multiline
                rows={4}
              />

              <Button
                type="submit"
                variant="contained"
                className="mt-2"
                sx={{
                  background: 'linear-gradient(45deg, #3498db, #2ecc71)',
                  fontWeight: 'bold'
                }}
              >
                SEND MESSAGE
              </Button>

            </form>
          </Paper>
        </div>

      </div>
    </div>
    </>
  );
};

export default Contact;