import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Divider,
  Table,
  TableHead,
  TableRow,
  TableCell,
  TableBody,
  CircularProgress
} from '@mui/material';
import useDocumentTitle from '../../../../hooks/useDocumentTitle';
import API_BASE_URL from "../../../../app/apiroutes";

const TourView = () => {
  const { id } = useParams();
  useDocumentTitle('View Tour');

  const [tour, setTour] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/tour/edit/${id}`, {
      headers: {
        Authorization: `Bearer ${localStorage.getItem('adminToken')}`
      }
    })
      .then(res => res.json())
      .then(result => {
        if (result.success) {
          setTour(result.data);
        }
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  }, [id]);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', mt: 5 }}>
        <CircularProgress />
      </Box>
    );
  }

  if (!tour) {
    return <Typography>No data found</Typography>;
  }

  return (
    <Box sx={{ p: 3 }}>
      <Card>
        <CardContent>

          {/* ===== HEADER ===== */}
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <img
                src={tour.image}
                alt={tour.tour_name}
                style={{ width: '100%', borderRadius: 8 }}
              />
            </Grid>

            <Grid item xs={12} md={8}>
              <Typography variant="h5" fontWeight="bold">
                {tour.tour_name}
              </Typography>

              <Typography mt={1}>Days: {tour.days}</Typography>
              <Typography>Price: ₹ {tour.price}</Typography>
              <Typography>Discount: {tour.discount}%</Typography>
            </Grid>
          </Grid>

          <Divider sx={{ my: 3 }} />

          {/* ===== DESCRIPTION ===== */}
          <Typography variant="h6">Description</Typography>
         <Typography
            variant="body1"
            component="div"
            sx={{
              fontSize: { xs: "0.9rem", md: "1rem" },
              lineHeight: 1.6,
              color: "text.secondary",
              "& p": { margin: "0 0 10px 0" },
              "& strong": { fontWeight: 700 },
              "& i": { fontStyle: "italic" }
            }}
            dangerouslySetInnerHTML={{ __html: tour.description }}
          />

          <Divider sx={{ my: 3 }} />

          {/* ===== INCLUDE / EXCLUDE ===== */}
          <Grid container spacing={2}>
            <Grid item xs={12} md={6}>
              <Typography variant="h6">Include</Typography>
              <ul>
                {tour.include?.length > 0 ? (
                  tour.include.map((item, index) => (
                    <li key={index}>{item}</li>
                  ))
                ) : (
                  <li>No include data</li>
                )}
              </ul>
            </Grid>

            <Grid item xs={12} md={6}>
              <Typography variant="h6">Exclude</Typography>
              <ul>
                {tour.exclude?.length > 0 ? (
                  tour.exclude.map((item, index) => (
                    <li key={index}>{item}</li>
                  ))
                ) : (
                  <li>No exclude data</li>
                )}
              </ul>
            </Grid>
          </Grid>

          <Divider sx={{ my: 3 }} />

          {/* ===== ITINERARY ===== */}
          <Typography variant="h6">Itinerary</Typography>

          {tour.itinerary?.length > 0 ? (
            tour.itinerary.map((item, index) => (
              <Box key={index} sx={{ mt: 2, pl: 2 }}>
                <Typography fontWeight="bold">
                  {item.day} - {item.title}
                </Typography>
                <Typography variant="body2">
                  {item.description}
                </Typography>
              </Box>
            ))
          ) : (
            <Typography>No itinerary available</Typography>
          )}

          <Divider sx={{ my: 3 }} />

          {/* ===== LOCATIONS ===== */}
          <Typography variant="h6">Locations</Typography>
          <ul>
            {tour.locations?.length > 0 ? (
              tour.locations.map((loc, index) => (
                <li key={index}>{loc}</li>
              ))
            ) : (
              <li>No locations found</li>
            )}
          </ul>

          <Divider sx={{ my: 3 }} />

          {/* ===== GALLERY ===== */}
          <Typography variant="h6">Gallery</Typography>

          <Grid container spacing={2} mt={1}>
            {tour.images?.length > 0 ? (
              tour.images.map((img, index) => (
                <Grid item xs={6} md={3} key={index}>
                  <img
                    src={img}
                    alt="Tour"
                    style={{ width: '100%', borderRadius: 6 }}
                  />
                </Grid>
              ))
            ) : (
              <Typography>No images available</Typography>
            )}
          </Grid>

          <Divider sx={{ my: 3 }} />

          {/* ===== PRICING SLABS ===== */}
          <Typography variant="h6" gutterBottom>
            Pricing Slabs
          </Typography>

          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell><b>Min</b></TableCell>
                <TableCell><b>Max</b></TableCell>
                <TableCell><b>Price</b></TableCell>
              </TableRow>
            </TableHead>

            <TableBody>
              {tour.pricing_slabs?.length > 0 ? (
                tour.pricing_slabs.map((row, index) => (
                  <TableRow key={index}>
                    <TableCell>{row.min}</TableCell>
                    <TableCell>{row.max}</TableCell>
                    <TableCell>₹ {row.price}</TableCell>
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell colSpan={3} align="center">
                    No pricing slabs
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>

        </CardContent>
      </Card>
    </Box>
  );
};

export default TourView;