import React, { useEffect, useState } from "react";
import axios from "axios";
import useDocumentTitle from "../../../../hooks/useDocumentTitle";
import API_BASE_URL from "../../../../app/apiroutes";

const GSTSettings = () => {

  useDocumentTitle("GST Settings");

  const [gst, setGst] = useState({
    gst_percentage: "",
    gst_number: "",
    company_name: "",
    state_code: ""
  });

  const [loading, setLoading] = useState(false);

  // GET GST SETTINGS
  const fetchGST = async () => {
    try {

      const res = await axios.get(`${API_BASE_URL}/api/gst-settings`, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("adminToken")}`
        }
      });

      if (res.data.success && res.data.data) {

        setGst({
          gst_percentage: res.data.data.gst_percentage || "",
          gst_number: res.data.data.gst_number || "",
          company_name: res.data.data.company_name || "",
          state_code: res.data.data.state_code || ""
        });

      }

    } catch (error) {
      console.error("GST Fetch Error:", error);
    }
  };

  useEffect(() => {
    fetchGST();
  }, []);

  // UPDATE GST SETTINGS
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {

      setLoading(true);

      const res = await axios.post(
        `${API_BASE_URL}/api/gst-settings/update`,
        gst,
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("adminToken")}`
          }
        }
      );

      if (res.data.success) {
        alert("GST Settings Updated Successfully");
      }

    } catch (error) {
      console.error("GST Update Error:", error);
    }

    setLoading(false);
  };

  const handleChange = (e) => {
    setGst({
      ...gst,
      [e.target.name]: e.target.value
    });
  };

  return (
    <div className="dashboard p-4">

      <h2>GST Settings</h2>

      <form onSubmit={handleSubmit}>

        <input
          name="gst_percentage"
          className="form-control mb-2"
          placeholder="GST Percentage"
          value={gst.gst_percentage}
          onChange={handleChange}
        />

        <input
          name="gst_number"
          className="form-control mb-2"
          placeholder="GST Number"
          value={gst.gst_number}
          onChange={handleChange}
        />

        <input
          name="company_name"
          className="form-control mb-2"
          placeholder="Company Name"
          value={gst.company_name}
          onChange={handleChange}
        />

        <input
          name="state_code"
          className="form-control mb-2"
          placeholder="State Code"
          value={gst.state_code}
          onChange={handleChange}
        />

        <button className="btn btn-success" disabled={loading}>
          {loading ? "Saving..." : "Save GST"}
        </button>

      </form>

    </div>
  );
};

export default GSTSettings;