import { Route, Routes, Navigate, Outlet } from 'react-router-dom';
import AdminLayout from '../features/admin/components/AdminLayout/AdminLayout';

import AdminLogin from '../features/auth/admin/login';
import { AuthProvider, useAuth } from '../features/auth/admin/AuthContext';
import NotFound from '../components/Common/NotFound';
import Loader from '../features/Loader/Loader';
import Dashboard from '../features/admin/pages/Dashboard/Dashboard';
import AddNewTour from '../features/admin/pages/Tour/AddNewTour';
import TourList from '../features/admin/pages/Tour/TourList';
import TourView from '../features/admin/pages/Tour/TourView';
import TourOrderView from '../features/admin/pages/Tour/TourOrderView';
import GSTSettings from '../features/admin/pages/GST_Settings/GSTSettings';
import GalleryUpload from '../features/admin/pages/GST_Settings/GalleryUpload';
import PendingOrderList from '../features/admin/pages/Tour/PendingOrderList';
import ConfirmOrderList from '../features/admin/pages/Tour/ConfirmOrderList';
import PickupOrderList from '../features/admin/pages/Tour/PickupOrderList';
import ComplateOrderList from '../features/admin/pages/Tour/ComplateOrderList';
import RefundOrderList from '../features/admin/pages/Tour/RefundOrderList';
import CancelOrderList from '../features/admin/pages/Tour/CancelOrderList';
import UpdateTour from '../features/admin/pages/Tour/UpdateTour';
import CustomerList from '../features/admin/pages/Customer/CustomerList';
import BusinessSettings from '../features/admin/pages/GST_Settings/BusinessSettings';
import ContactList from "../features/admin/pages/Customer/ContactList";

const ProtectedRoute = ({ requiredRole }) => {
  const { user, loading, isAuthenticated } = useAuth();

  if (loading) {
    return <Loader />;
  }

  if (!isAuthenticated) {
    return <Navigate to="/admin/login" replace />;
  }

  if (requiredRole && user?.role !== requiredRole) {
    return <Navigate to="/admin/unauthorized" replace />;
  }

  return <Outlet />;
};
const PublicRoute = ({ children }) => {
  const { isAuthenticated, loading } = useAuth();

  if (loading) {
    return <Loader />;
  }

  if (isAuthenticated) {
    return <Navigate to="/admin/dashboard" replace />;
  }

  return children;
};

function AppContent() {
  return (
    <Routes>
      <Route path="/"></Route>
      <Route path="/login" element={
        <PublicRoute>
          <AdminLogin />
        </PublicRoute>
      } />

      <Route element={<ProtectedRoute />}>
        <Route element={<AdminLayout />}>
          <Route index element={<Navigate to="/admin/dashboard" replace />} />
          <Route path="/dashboard" element={<Dashboard />} />
          <Route path="/add-new-tour" element={<AddNewTour />} />
          <Route path="/tour-list" element={<TourList />} />
          <Route path="/customer-list" element={<CustomerList />} />
          <Route path="/tours/view/:id" element={<TourView />} />
          <Route path="/tours/edit/:id" element={<UpdateTour />} />
          <Route path="/pending-order-list" element={<PendingOrderList />} />
          <Route path="/confirm-order-list" element={<ConfirmOrderList />} />
          <Route path="/pickup-order-list" element={<PickupOrderList />} />
          <Route path="/complate-order-list" element={<ComplateOrderList />} />
          <Route path="/refund-order-list" element={<RefundOrderList />} />
          <Route path="/cancel-order-list" element={<CancelOrderList />} />
          <Route path="/tour-orders/view/:id" element={<TourOrderView />} />
          <Route path="/gst-settings" element={<GSTSettings />} />
          <Route path="/gallery-image" element={<GalleryUpload />} />
          <Route path="/business-settings" element={<BusinessSettings />} />
          <Route path="/customer-contact" element={<ContactList />} />
        </Route>
      </Route>

      <Route path="/unauthorized" element={<NotFound type="unauthorized" />} />
      <Route path="/404" element={<NotFound />} />

      {/* Catch all route */}
      <Route path="*" element={<Navigate to="/admin/404" replace />} />
    </Routes>
  );
}

function AdminRoutes() {
  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
}

export default AdminRoutes;
