import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  Box,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  Typography,
  CircularProgress,
  Alert,
  Chip,
  IconButton
} from '@mui/material';
import { Visibility, Edit, Delete } from '@mui/icons-material';
import useDocumentTitle from '../../../../hooks/useDocumentTitle';
import API_BASE_URL from "../../../../app/apiroutes";

const TourList = () => {
  useDocumentTitle('Tour List');

  const [tours, setTours] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchTours();
  }, []);
  const token = localStorage.getItem('adminToken');

  if (!token) {
    throw new Error('Unauthorized. Please login again.');
  }
  const fetchTours = async () => {
    try {
      setLoading(true);
      const response = await fetch(`${API_BASE_URL}/api/tour`);
      const data = await response.json();

      if (data.success) {
        setTours(data.data);
      } else {
        setError(data.message || 'Failed to fetch tours');
      }
    } catch (error) {
      console.error('Error fetching tours:', error);
      setError('Failed to fetch tours. Please check your connection.');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this tour?')) {
      try {
        const response = await fetch(`${API_BASE_URL}/api/tour/delete/${id}`, {
          method: 'DELETE',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${localStorage.getItem('adminToken')}`,
          }
        });
        const data = await response.json();

        if (data.success) {
          alert('Tour deleted successfully');
          fetchTours(); // Refresh the list
        } else {
          alert(data.message || 'Failed to delete tour');
        }
      } catch (error) {
        console.error('Error deleting tour:', error);
        alert('Failed to delete tour');
      }
    }
  };

  const handleStatusToggle = async (id, currentStatus) => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/tour/status-update/${id}`, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${localStorage.getItem('adminToken')}` // Add if using authentication
        }
      });
      const data = await response.json();

      if (data.success) {
        alert(data.message);
        fetchTours(); // Refresh the list
      } else {
        alert(data.message || 'Failed to update status');
      }
    } catch (error) {
      console.error('Error updating status:', error);
      alert('Failed to update status');
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '50vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ m: 2 }}>
        {error}
      </Alert>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h4" fontWeight={600}>
          Tour List
        </Typography>
        <Button
          component={Link}
          to="/admin/add-new-tour"
          variant="contained"
          color="primary"
        >
          Add New Tour
        </Button>
      </Box>

      {tours.length === 0 ? (
        <Alert severity="info">No tours found. Create your first tour!</Alert>
      ) : (
        <Paper sx={{ width: '100%', overflow: 'hidden' }}>
          <TableContainer>
            <Table stickyHeader>
              <TableHead>
                <TableRow>
                  <TableCell>#</TableCell>
                  <TableCell>Tour Name</TableCell>
                  <TableCell>Days</TableCell>
                  <TableCell>Price</TableCell>
                  <TableCell>Discount</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {tours.map((tour, index) => (
                  <TableRow key={tour.id} hover>
                    <TableCell>{index + 1}</TableCell>
                    <TableCell>
                      <Typography variant="body1" fontWeight={500}>
                        {tour.tour_name}
                      </Typography>
                    </TableCell>
                    <TableCell>{tour.days}</TableCell>
                    <TableCell>₹{tour.price}</TableCell>
                    <TableCell>{tour.discount}%</TableCell>
                    <TableCell>
                      <Chip
                        label={tour.status === 1 ? 'Active' : 'Inactive'}
                        color={tour.status === 1 ? 'success' : 'error'}
                        size="small"
                        onClick={() => handleStatusToggle(tour.id, tour.status)}
                        sx={{ cursor: 'pointer' }}
                      />
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', gap: 1 }}>
                        <IconButton
                          component={Link}
                          to={`/admin/tours/view/${tour.id}`}
                          color="primary"
                          size="small"
                          title="View"
                        >
                          <Visibility fontSize="small" />
                        </IconButton>
                        <IconButton
                          component={Link}
                          to={`/admin/tours/edit/${tour.id}`}
                          color="secondary"
                          size="small"
                          title="Edit"
                        >
                          <Edit fontSize="small" />
                        </IconButton>
                        <IconButton
                          onClick={() => handleDelete(tour.id)}
                          color="error"
                          size="small"
                          title="Delete"
                        >
                          <Delete fontSize="small" />
                        </IconButton>
                      </Box>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      )}
    </Box>
  );
};

export default TourList;